<?php
require_once 'common.php';pageStart('Representative Account & Clients');
$sql='SELECT r.first_name AS rep_first,r.last_name AS rep_last,r.representative_id,r.phone AS rep_phone,r.email AS rep_email,c.client_id,c.first_name AS client_first,c.last_name AS client_last,p.street_number,p.street_name,p.city,p.state,p.zip_code,p.phone AS client_phone,m.moving_id,m.destination_street_number,m.destination_street_name,m.destination_city,m.destination_state,m.destination_zip,m.moving_date,m.total_weight,m.miles,m.total_cost,s.instructions FROM representatives r LEFT JOIN representative_clients rc ON rc.representative_id=r.representative_id LEFT JOIN clients c ON c.client_id=rc.client_id LEFT JOIN client_personal_info p ON p.client_id=c.client_id LEFT JOIN moving_events m ON m.client_id=c.client_id AND m.representative_id=r.representative_id LEFT JOIN special_instructions s ON s.moving_id=m.moving_id WHERE r.representative_id=? ORDER BY c.last_name,m.moving_date';
$st=$pdo->prepare($sql);$st->execute([$repId]);$rows=$st->fetchAll();
if(!$rows)message('No representative account found.');else{echo '<p>Only clients associated with your representative account are shown.</p><div class="table-wrap"><table><thead><tr>';$cols=['rep_first'=>'Rep First','rep_last'=>'Rep Last','representative_id'=>'Rep ID','rep_phone'=>'Rep Phone','rep_email'=>'Rep Email','client_first'=>'Client First','client_last'=>'Client Last','client_id'=>'Client ID','street_number'=>'Street #','street_name'=>'Street','city'=>'City','state'=>'State','zip_code'=>'ZIP','client_phone'=>'Client Phone','destination_street_number'=>'New Street #','destination_street_name'=>'New Street','destination_city'=>'New City','destination_state'=>'New State','destination_zip'=>'New ZIP','moving_date'=>'Move Date','total_weight'=>'Weight','miles'=>'Miles','total_cost'=>'Cost','instructions'=>'Special Instructions'];foreach($cols as $label)echo '<th>'.h($label).'</th>';echo '</tr></thead><tbody>';foreach($rows as $row){echo '<tr>';foreach($cols as $key=>$label)echo '<td>'.h($row[$key]??'').'</td>';echo '</tr>';}echo '</tbody></table></div>';}
pageEnd();
